  "promptResolution": {
    "ruWithoutExplicitPrompt": "",
    "enUsWithoutExplicitPrompt": "Transcribe the audio.",
    "ruWithExplicitPrompt": "Transcribe verbatim in Russian."
  },
  "multipartFields": {
    "ruHasPromptField": false,
    "ruFields": [
      {
        "name": "file",
        "kind": "file",
        "value": "[binary]"
      },
      {
        "name": "model",
        "kind": "field",
        "value": "whisper-large-v3-turbo"
      },
      {
        "name": "language",
        "kind": "field",
        "value": "ru"
      }
    ],
